public class LinkedListCycleII {
    static class ListNode {
        int val;
        ListNode next;
        ListNode(int v) { val = v; }
    }

    public ListNode detectCycle(ListNode head) {
        // 第一阶段：快慢指针判圈
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {            // 相遇，确认有环
                // 第二阶段：一个回 head，同速再走
                ListNode p = head;
                while (p != slow) {
                    p = p.next;
                    slow = slow.next;
                }
                return p;                  // 再次相遇处即入环口
            }
        }
        return null;                       // 无环
    }
}
